// VC2 part B: run the COP2 conformance cases through the code OUR recompiler emits (vucheck_ops.inc, generated by
// vucheck_gen.exe from ops.txt with the real VuTranslator) and diff against PCSX2 (pcsx2_results.bin).
// Usage: vucheck.exe [--selftest] [--rn] [--dir tools/vucheck] [--all]
#include <algorithm>
#include <bit>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

#if defined(_MSC_VER)
#include <intrin.h>
#else
#include <immintrin.h>
#endif

#include "ps2_runtime_macros.h"

// Stubs for externs referenced by ps2_runtime_macros.h / ps2_runtime.h (same idea as tools/fpucheck.cpp).
bool ps2xFpuProbeEnabled() { return false; }
void ps2xFpuProbe(void *, int) {}
uint32_t g_ps2wwBase = 0;
uint32_t g_ps2wwLen = 0;
bool g_an1 = false;
void ps2xAn1Ev(int, uint32_t, uint32_t, uint32_t) {}
void ps2xAn1Vec(int, __m128, __m128, __m128) {}
void ps2xAn1Fpu(int, float, float, float) {}

// ---- Q operations: copied VERBATIM from PS2Recomp/ps2xRuntime/src/lib/ps2_runtime.cpp (ps2xVu0Max ~6835,
// ps2xVu0DivImpl ~6878, ps2xVu0SqrtImpl ~6890, ps2xVu0RsqrtImpl ~6896), HW-Q mode (default), AN1 probe wrappers dropped.
static float ps2xVu0Max(uint32_t signBits)
{
    const uint32_t b = (signBits & 0x80000000u) | 0x7F7FFFFFu;
    float f;
    std::memcpy(&f, &b, sizeof(f));
    return f;
}
extern "C" float ps2x_vu0_div(float fs, float ft)
{
    uint32_t sb, tb;
    std::memcpy(&sb, &fs, sizeof(sb));
    std::memcpy(&tb, &ft, sizeof(tb));
    if (ft == 0.0f)
        return ps2xVu0Max(sb ^ tb);
    const float q = fs / ft;
    return std::isfinite(q) ? q : ps2xVu0Max(sb ^ tb);
}
extern "C" float ps2x_vu0_sqrt(float ft)
{
    return std::sqrt(std::fabs(ft));
}
extern "C" float ps2x_vu0_rsqrt(float fs, float ft)
{
    uint32_t sb, tb;
    std::memcpy(&sb, &fs, sizeof(sb));
    std::memcpy(&tb, &ft, sizeof(tb));
    if (ft == 0.0f)
        return ps2xVu0Max(sb ^ tb);
    const float q = fs / std::sqrt(std::fabs(ft));
    return std::isfinite(q) ? q : ps2xVu0Max(sb);
}

// VC3: verbatim from ps2_runtime.cpp ps2x_vu0_flags (first 8 lines, PROBE-M3 dropped)
extern "C" void ps2x_vu0_flags(R5900Context *ctx, __m128 res, int laneMask)
{
    const int sg = _mm_movemask_ps(res) & laneMask;
    const int zr = _mm_movemask_ps(_mm_cmpeq_ps(res, _mm_setzero_ps())) & laneMask;
    auto rv = [](int m) { return ((m & 1) << 3) | ((m & 2) << 1) | ((m & 4) >> 1) | ((m & 8) >> 3); };
    ctx->vu0_mac_flags = (static_cast<uint32_t>(rv(sg)) << 4) | static_cast<uint32_t>(rv(zr));
    const uint32_t now = (zr ? 1u : 0u) | (sg ? 2u : 0u); // Z, S (U/O not modelled)
    ctx->vu0_status = static_cast<uint16_t>((ctx->vu0_status & ~0xFu) | now | (now << 6) | (ctx->vu0_status & 0xFC0u));
}

struct VuOp
{
    const char *name;
    uint32_t word;
    void (*fn)(R5900Context *);
    int flagsModelled; // bit0 status, bit1 mac, bit2 clip (as detected in the emitted code text)
};

#include "vucheck_ops.inc" // op_vmula_seed, op_vmaddx_readback, op_0.., kOps[]

static const size_t kNumOps = sizeof(kOps) / sizeof(kOps[0]);
static constexpr size_t kNumCases = 32;
static constexpr size_t kCaseWords = 20; // vf1 vf2 vf6 vf7 (16) + I + Q + 2 pad
static constexpr size_t kRecWords = 16;  // vf3[4] acc[4] status mac clip Q I pad pad pad

struct Rec
{
    uint32_t w[kRecWords];
};

static bool readFile(const std::string &path, std::vector<uint8_t> &out)
{
    std::FILE *f = std::fopen(path.c_str(), "rb");
    if (!f)
        return false;
    std::fseek(f, 0, SEEK_END);
    long n = std::ftell(f);
    std::fseek(f, 0, SEEK_SET);
    out.resize((size_t)n);
    const size_t got = n ? std::fread(out.data(), 1, (size_t)n, f) : 0;
    std::fclose(f);
    return got == (size_t)n;
}

static void putVec(__m128 &dst, const uint32_t *w)
{
    dst = _mm_castsi128_ps(_mm_loadu_si128(reinterpret_cast<const __m128i *>(w)));
}
static void getVec(uint32_t *w, __m128 v)
{
    _mm_storeu_si128(reinterpret_cast<__m128i *>(w), _mm_castps_si128(v));
}

static Rec runCase(R5900Context *ctx, const VuOp &op, const uint32_t *in)
{
    std::memset(ctx, 0, sizeof(*ctx));
    ctx->vu0_vf[0] = _mm_set_ps(1.0f, 0.0f, 0.0f, 0.0f);
    putVec(ctx->vu0_vf[1], in + 0);
    putVec(ctx->vu0_vf[2], in + 4);
    putVec(ctx->vu0_vf[6], in + 8);
    putVec(ctx->vu0_vf[7], in + 12);
    op_vmula_seed(ctx); // ACC := vf6 * vf7 (VMULA.xyzw) through the emitted code
    std::memcpy(&ctx->vu0_i, &in[16], 4);
    std::memcpy(&ctx->vu0_q, &in[17], 4);
    ctx->vu0_status = 0;
    ctx->vu0_mac_flags = 0;
    ctx->vu0_clip_flags = 0;
    const uint32_t sent[4] = {0xDEADBEEFu, 0xDEADBEEFu, 0xDEADBEEFu, 0xDEADBEEFu};
    putVec(ctx->vu0_vf[3], sent);

    op.fn(ctx); // the ONE op under test

    Rec r{};
    uint32_t status = ctx->vu0_status;
    uint32_t mac = ctx->vu0_mac_flags;
    uint32_t clip = ctx->vu0_clip_flags & 0x00FFFFFFu; // as emitted CFC2 does
    uint32_t q, i;
    std::memcpy(&q, &ctx->vu0_q, 4);
    std::memcpy(&i, &ctx->vu0_i, 4);
    getVec(&r.w[0], ctx->vu0_vf[3]);
    op_vmaddx_readback(ctx); // vf5 = ACC + vf0*vf0.x
    getVec(&r.w[4], ctx->vu0_vf[5]);
    r.w[8] = status;
    r.w[9] = mac;
    r.w[10] = clip;
    r.w[11] = q;
    r.w[12] = i;
    return r;
}

static bool isDenorm(uint32_t v) { return (v & 0x7F800000u) == 0 && (v & 0x007FFFFFu) != 0; }
static bool isExp255(uint32_t v) { return (v & 0x7F800000u) == 0x7F800000u; }

// KNOWN = case has denormal / exp255 inputs (any operand word), or the diff is only the max clamp 0x7fffffff vs 0x7f7fffff.
static bool caseHasOddInputs(const uint32_t *in)
{
    for (int k = 0; k < 18; ++k)
        if (isDenorm(in[k]) || isExp255(in[k]))
            return true;
    return false;
}
static bool isClampDiff(uint32_t a, uint32_t b)
{
    const uint32_t sa = a & 0x80000000u, sb = b & 0x80000000u;
    if (sa != sb)
        return false;
    const uint32_t ma = a & 0x7FFFFFFFu, mb = b & 0x7FFFFFFFu;
    return (ma == 0x7FFFFFFFu && mb == 0x7F7FFFFFu) || (mb == 0x7FFFFFFFu && ma == 0x7F7FFFFFu);
}

int main(int argc, char **argv)
{
    bool selftest = false, rn = false, showAll = false;
    std::string dir = "tools/vucheck";
    bool flagsMode = false, normalMode = false;
    std::string flagsOut = "logs/vucheck_flags.txt";
    for (int i = 1; i < argc; ++i)
    {
        if (!std::strcmp(argv[i], "--selftest")) selftest = true;
        else if (!std::strcmp(argv[i], "--rn")) rn = true;
        else if (!std::strcmp(argv[i], "--all")) showAll = true;
        else if (!std::strcmp(argv[i], "--flags")) flagsMode = true;
        else if (!std::strcmp(argv[i], "--normal")) { normalMode = true; flagsOut = "logs/vucheck_flags_normal.txt"; }
        else if (!std::strcmp(argv[i], "--flags-out") && i + 1 < argc) flagsOut = argv[++i];
        else if (!std::strcmp(argv[i], "--dir") && i + 1 < argc) dir = argv[++i];
    }
    if (!rn)
    {
        const char *rtz = std::getenv("PS2X_EE_RTZ");
        if (!(rtz && rtz[0] == '0'))
            _mm_setcsr(_mm_getcsr() | 0x6000u);
    }
    std::printf("MXCSR=0x%08x (%s)\n", _mm_getcsr(), rn ? "RN" : "RTZ");

    std::vector<uint8_t> inb;
    if (!readFile(dir + "/inputs.bin", inb) || inb.size() < kNumCases * kCaseWords * 4)
    {
        std::fprintf(stderr, "cannot read %s/inputs.bin (need %zu bytes)\n", dir.c_str(), kNumCases * kCaseWords * 4);
        return 1;
    }
    const uint32_t *inputs = reinterpret_cast<const uint32_t *>(inb.data());

    static R5900Context ctx;
    std::vector<Rec> ours(kNumOps * kNumCases);
    for (size_t o = 0; o < kNumOps; ++o)
        for (size_t c = 0; c < kNumCases; ++c)
            ours[o * kNumCases + c] = runCase(&ctx, kOps[o], inputs + c * kCaseWords);

    if (selftest)
    {
        std::printf("selftest: ran %zu ops x %zu cases = %zu records, no crash\n", kNumOps, kNumCases, ours.size());
        int unmodelled = 0;
        for (size_t o = 0; o < kNumOps; ++o)
            if (!(kOps[o].flagsModelled & 7))
                ++unmodelled;
        std::printf("selftest: %d/%zu ops emit no status/mac/clip update (FLAGS-NOT-MODELLED)\n", unmodelled, kNumOps);
        return 0;
    }

    std::vector<uint8_t> refb;
    if (!readFile(dir + "/pcsx2_results.bin", refb) || refb.size() < kNumOps * kNumCases * 64)
    {
        std::fprintf(stderr, "cannot read %s/pcsx2_results.bin (need %zu bytes; use --selftest until it exists)\n",
                     dir.c_str(), kNumOps * kNumCases * 64);
        return 1;
    }
    const Rec *ref = reinterpret_cast<const Rec *>(refb.data());

    if (flagsMode)
    {
        FILE *fo = std::fopen(flagsOut.c_str(), "w");
        if (!fo) { std::fprintf(stderr, "cannot write %s\n", flagsOut.c_str()); return 1; }
        static const char *stN[12] = {"Z", "S", "U", "O", "I", "D", "ZS", "SS", "US", "OS", "IS", "DS"};
        static const char *mk[4] = {"zero", "sign", "under", "over"};
        static const char *ln = "xyzw";
        int stP[12] = {}, stO[12] = {}, mcP[16] = {}, mcO[16] = {};
        std::vector<int> stEx(12, 0), mcEx(16, 0);
        char buf[256];
        std::string body, examples, unpatched;
        int clipTot = 0, nOp = 0, nUn = 0; std::vector<int> topCnt(kNumOps, 0);
        for (size_t o = 0; o < kNumOps; ++o)
        {
            int ds = 0, dm = 0, dc = 0;
            int pnz = 0;
            for (size_t c = 0; c < kNumCases; ++c)
            {
                const Rec &p = ref[o * kNumCases + c];
                const Rec &u = ours[o * kNumCases + c];
                const uint32_t *in = inputs + c * kCaseWords;
                if (normalMode && caseHasOddInputs(in)) continue;
                const uint32_t ps = p.w[8] & 0xFFFF, us = u.w[8] & 0xFFFF;
                if (((ps ^ us) & 3) || ((p.w[9] ^ u.w[9]) & 0xFF)) ++topCnt[o];
                std::string cls = " res=";
                { const bool sent = p.w[0] == 0xDEADBEEFu && p.w[1] == 0xDEADBEEFu; for (int l = 0; l < 4; ++l) { const uint32_t v = p.w[sent ? 4 + l : l]; const uint32_t m = v & 0x7FFFFFFFu; cls += (m == 0) ? "Z" : ((m & 0x7F800000u) == 0 ? "D" : ((m & 0x7F800000u) == 0x7F800000u ? "E" : "N")); } }
                (void)0;
                ds += ps != us; dm += p.w[9] != u.w[9]; dc += p.w[10] != u.w[10];
                if (p.w[8] || p.w[9]) ++pnz;
                auto note = [&](int *ex, int idx, const char *nm, uint32_t pv, uint32_t uv) {
                    if (ex[idx]++ >= 6) return;
                    std::snprintf(buf, sizeof buf, "  %s %s case %zu pcsx2=%08x ours=%08x%s in vf1=%08x,%08x,%08x,%08x vf2=%08x,%08x,%08x,%08x\n",
                                  nm, kOps[o].name, c, pv, uv, cls.c_str(), in[0], in[1], in[2], in[3], in[4], in[5], in[6], in[7]);
                    examples += buf;
                };
                for (int b = 0; b < 12; ++b)
                {
                    const int pb = (ps >> b) & 1, ub = (us >> b) & 1;
                    if (pb && !ub) ++stP[b];
                    if (ub && !pb) ++stO[b];
                    if (pb != ub) note(stEx.data(), b, stN[b], ps, us);
                }
                for (int b = 0; b < 16; ++b)
                {
                    const int pb = (p.w[9] >> b) & 1, ub = (u.w[9] >> b) & 1;
                    if (pb && !ub) ++mcP[b];
                    if (ub && !pb) ++mcO[b];
                    if (pb != ub) note(mcEx.data(), b, "mac", p.w[9], u.w[9]);
                }
            }
            clipTot += dc;
            const bool patched = kOps[o].flagsModelled & 8;
            std::snprintf(buf, sizeof buf, "%s: flags: status %d/32 mac %d/32 clip %d/32%s", kOps[o].name, ds, dm, dc, patched ? "" : " [unp]");
            if (ds || dm || dc) { body += buf; body += (++nOp % 6) ? " | " : "\n"; }
            if (!patched && pnz)
            {
                std::snprintf(buf, sizeof buf, "%s %d/32", kOps[o].name, pnz);
                unpatched += buf; unpatched += (++nUn % 5) ? ", " : "\n";
            }
        }
        std::string t = "== bit table: count(pcsx2=1,ours=0) / count(ours=1,pcsx2=0) over all op x case ==\n";
        for (int b = 0; b < 12; ++b) { std::snprintf(buf, sizeof buf, "status %-2s (bit %2d): %5d / %5d\n", stN[b], b, stP[b], stO[b]); t += buf; }
        for (int k = 0; k < 4; ++k)
            for (int l = 0; l < 4; ++l)
            {
                const int b = k * 4 + (3 - l); // bit layout: bit0=w .. bit3=x per nibble
                std::snprintf(buf, sizeof buf, "mac %-5s.%c (bit %2d): %5d / %5d\n", mk[k], ln[l], b, mcP[b], mcO[b]); t += buf;
            }
        { std::vector<size_t> ord(kNumOps); for (size_t i = 0; i < kNumOps; ++i) ord[i] = i; std::sort(ord.begin(), ord.end(), [&](size_t a, size_t b) { return topCnt[a] > topCnt[b]; }); t += "== top 15 ops by cases where status Z/S or MAC sign/zero differ ==\n"; for (int i = 0; i < 15; ++i) { std::snprintf(buf, sizeof buf, "  %s %d%s\n", kOps[ord[i]].name, topCnt[ord[i]], (kOps[ord[i]].flagsModelled & 8) ? "" : " [unpatched]"); t += buf; } }
        std::fputs(t.c_str(), fo);
        std::fputs("== examples (first 6 per differing bit; pcsx2/ours = full status or mac word) ==\n", fo);
        std::fputs(examples.c_str(), fo);
        std::fputs("== ops NOT patched by the game (flags stay 0 in ours) where PCSX2 status|mac != 0 ==\n", fo);
        std::fputs(unpatched.c_str(), fo);
        std::fputs("== per op ==\n", fo);
        std::fputs(body.c_str(), fo); std::fputs("\n", fo);
        std::fclose(fo);
        std::printf("flags report -> %s (clip mismatches total %d)\n%s", flagsOut.c_str(), clipTot, t.c_str());
        return 0;
    }

    struct Sum { size_t op; int real; };
    std::vector<Sum> sums;
    static const char *kLane = "xyzw";
    for (size_t o = 0; o < kNumOps; ++o)
    {
        int mm[6] = {0, 0, 0, 0, 0, 0}; // vf3 acc status mac clip Q (any-lane counts per case)
        int real = 0, known = 0, shown = 0;
        const bool flagsUnmodelled = !(kOps[o].flagsModelled & 7);
        const bool modelClip = kOps[o].flagsModelled & 4;
        for (size_t c = 0; c < kNumCases; ++c)
        {
            const Rec &p = ref[o * kNumCases + c];
            const Rec &u = ours[o * kNumCases + c];
            const uint32_t *in = inputs + c * kCaseWords;
            const bool odd = caseHasOddInputs(in);
            auto cmp = [&](int idx, int field, const char *label, int lane) {
                if (p.w[idx] == u.w[idx])
                    return;
                ++mm[field];
                const bool kn = odd || isClampDiff(p.w[idx], u.w[idx]);
                if (kn) { ++known; return; }
                ++real;
                if (shown < 4)
                {
                    ++shown;
                    const uint32_t a = lane >= 0 ? in[lane] : 0, b = lane >= 0 ? in[4 + lane] : 0;
                    std::printf("   REAL %s case %zu %s%c a=%08x b=%08x pcsx2=%08x ours=%08x\n", kOps[o].name, c, label,
                                lane >= 0 ? kLane[lane] : ' ', a, b, p.w[idx], u.w[idx]);
                }
            };
            for (int l = 0; l < 4; ++l) cmp(l, 0, "vf3.", l);
            for (int l = 0; l < 4; ++l) cmp(4 + l, 1, "acc.", l);
            if (!flagsUnmodelled)
            {
                if (kOps[o].flagsModelled & 1) cmp(8, 2, "status", -1);
                if (kOps[o].flagsModelled & 2) cmp(9, 3, "mac", -1);
                if (modelClip) cmp(10, 4, "clip", -1);
            }
            cmp(11, 5, "Q", -1);
        }
        // note: mismatch counts above are per lane/field (a case can contribute up to 4 to vf3/acc)
        std::printf("op %s: vf3 %d/32 acc %d/32 status %d/32 mac %d/32 clip %d/32 Q %d/32 [REAL %d KNOWN %d]%s\n",
                    kOps[o].name, mm[0], mm[1], mm[2], mm[3], mm[4], mm[5], real, known,
                    flagsUnmodelled ? " FLAGS-NOT-MODELLED" : "");
        if (real) sums.push_back({o, real});
    }
    std::sort(sums.begin(), sums.end(), [](const Sum &a, const Sum &b) { return a.real > b.real; });
    std::printf("\n== summary: ops with REAL>0 (%zu of %zu), sorted by count (lane/field mismatches) ==\n", sums.size(), kNumOps);
    for (const Sum &s : sums)
        std::printf("  %-18s REAL %d\n", kOps[s.op].name, s.real);
    (void)showAll;
    return 0;
}

